using AcxiomCRM.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Controllers;
[Authorize] public class ReportsController(ApplicationDbContext db):Controller { public async Task<IActionResult>Index(){var admin=User.IsInRole("Admin");var manager=User.IsInRole("Manager");var uid=User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value;var customers=db.Customers.AsQueryable();var leads=db.Leads.AsQueryable();var opps=db.Opportunities.AsQueryable();var followups=db.FollowUps.AsQueryable();if(!admin&&!manager){customers=customers.Where(x=>x.OwnerId==uid);leads=leads.Where(x=>x.AssignedTo==uid);opps=opps.Where(x=>x.AssignedTo==uid);followups=followups.Where(x=>x.AssignedTo==uid);}ViewBag.Customers=await customers.CountAsync();ViewBag.Leads=await leads.CountAsync();ViewBag.Converted=await leads.CountAsync(x=>x.Status=="Converted");ViewBag.Followups=await followups.CountAsync();ViewBag.Overdue=await followups.CountAsync(x=>x.Status=="Planned"&&x.FollowUpDate<DateTime.Today);ViewBag.Pipeline=await opps.Where(x=>x.Status=="Open").SumAsync(x=>(decimal?)x.Amount)??0m;ViewBag.Won=await opps.CountAsync(x=>x.Stage=="Won");return View();} }
